  "pf-apm-status-5xx": "5xx Σφάλμα Διακομιστή",
  "pf-apm-empty-chart": "Δεν υπάρχουν αρκετά δεδομένα για την απόδοση αυτού του γραφήματος ακόμη.",
  "pf-sa-title": "Ρυθμίσεις Πλατφόρμας",
  "pf-sa-desc": "Κάθε ρύθμιση της πλατφόρμας βρίσκεται εδώ. Ρυθμίζεται μία φορά και ισχύει για κάθε tenant.",
  "pf-sa-access-required": "Απαιτείται πρόσβαση super διαχειριστή",
  "pf-sa-access-desc": "Η προβολή αυτή είναι περιορισμένη σε χρήστες super_admin. Αν πιστεύετε ότι πρέπει να έχετε πρόσβαση, επικοινωνήστε με τον ιδιοκτήτη της πλατφόρμας.",
  "pf-sa-tab-security": "Ασφάλεια",
