  "ref-ag-doc-title": "Συμφωνητικό Συνεργασίας Παραπομπής και Προμήθειας",
  "ref-ag-doc-version": "Έκδοση",
  "ref-ag-doc-activated": "Ενεργοποιήθηκε",
  "ref-ag-s1-title": "1. Μέρη και σκοπός",
  "ref-ag-s1-body": "Το παρόν συμφωνητικό καθορίζει τη συνεργασία μεταξύ της εταιρείας που λειτουργεί την πλατφόρμα και εσάς ως συνεργάτη παραπομπής: συστήνετε εταιρείες-πελάτες και εμπορικές ευκαιρίες, και αποκτάτε προμήθεια από τις ολοκληρωμένες συναλλαγές που συνάπτονται με τις εταιρείες που παραπέμπετε.",
  "ref-ag-s2-title": "2. Ο ρόλος σας ως συνεργάτη παραπομπής",
  "ref-ag-s2-l1": "Συστήνετε εταιρείες-πελάτες και εμπορικές ευκαιρίες που εκπροσωπείτε ή με τις οποίες έχετε πραγματική σχέση.",
  "ref-ag-s2-l2": "Βεβαιώνετε ότι είστε ελεύθεροι να συστήσετε αυτές τις εταιρείες και ότι κάτι τέτοιο δεν παραβιάζει καμία υποχρέωσή σας απέναντι σε τρίτους.",
  "ref-ag-s2-l3": "Η εταιρεία που συστήνετε παραμένει παραπομπή σας: οι συναλλαγές που συνάπτονται μαζί της αποφέρουν την προμήθειά σας υπό τους παρακάτω όρους.",
  "ref-ag-s3-title": "3. Προμήθεια",
  "ref-ag-s3-body": "Για συναλλαγές που συνάπτονται με εταιρείες που παραπέμπετε, αποκτάτε προμήθεια υπό τους εξής όρους:",
  "ref-ag-s4-title": "4. Όροι καταβολής",
  "ref-ag-s4-body": "Η προμήθεια καθίσταται απαιτητή όταν η παραπεμπομένη συναλλαγή επιβεβαιωθεί ως ολοκληρωμένη, παρασχεθούν όλα τα απαιτούμενα έγγραφα και η προμήθεια εγκριθεί. Οι καταβολές γίνονται στον τραπεζικό λογαριασμό που ορίζετε στα «Στοιχεία καταβολής».",
  "ref-ag-s5-title": "5. Εμπιστευτικότητα",
  "ref-ag-s5-body": "Οι όροι του παρόντος συμφωνητικού, η ταυτότητα των παραπεμπομένων εταιρειών και όλες οι εμπορικές πληροφορίες που ανταλλάσσονται είναι εμπιστευτικές και δεν επιτρέπεται να κοινοποιηθούν σε τρίτους.",
  "ref-ag-s6-title": "6. Διάρκεια και αλλαγές",
  "ref-ag-s6-body": "Το συμφωνητικό ισχύει από την αποδοχή έως τη γραπτή λύση του. Όταν οι όροι αλλάζουν, εκδίδεται νέα έκδοση και απαιτείται η εκ νέου αποδοχή σας· η προηγούμενη αποδοχή σας παραμένει καταγεγραμμένη.",
  "ref-ag-custom-title": "Ειδικοί όροι",
  "ref-sign-form-title": "Υπογραφή συμφωνητικού",
  "ref-sign-typed-name": "Το πλήρες νομικό σας όνομα",
  "ref-sign-name-placeholder": "π.χ. Nikola Petrović",
  "ref-sign-name-hint": "Πληκτρολογήστε το όνομά σας ακριβώς όπως στα νομικά σας έγγραφα — αυτή είναι η ηλεκτρονική σας υπογραφή.",
  "ref-sign-consent": "Έχω διαβάσει και κατανοήσει το παραπάνω συμφωνητικό και αποδέχομαι τους όρους του. Βεβαιώνω ότι είμαι εξουσιοδοτημένος/η να το αποδεχθώ για λογαριασμό του λογαριασμού του συνεργάτη.",
  "ref-sign-button": "Υπογραφή συμφωνητικού",
